import { Request, Response, RequestHandler } from 'express';

import { Logger } from '..';

declare namespace createRequestMiddleware {
    interface Data {
        req: Request;
        res: Response;
        err?: Error;
    }

    export type MessageCreator = (data: Data, closed?: boolean) => void;
}

declare function createRequestMiddleware(
    logger: Logger,
    messageCreator?: createRequestMiddleware.MessageCreator
): RequestHandler;

export = createRequestMiddleware;
